const mdFiles = $input.all();
const projectName = $('Split Out').first().json.projectName;

const fs = require('fs');
const projectBase = `/shared/projects/${projectName}`;
fs.mkdirSync(projectBase, { recursive: true });
fs.mkdirSync(`${projectBase}/capitoli`, { recursive: true });

// Legge la cartella images/ dal filesystem e costruisce mappa pageNum → [filenames]
const imagesDir = `${projectBase}/images`;
const imagesByPage = {};
try {
  const imgFiles = fs.readdirSync(imagesDir);
  for (const f of imgFiles) {
    const m = f.match(/^img_pag_(\d+)_/);
    if (m) {
      const p = parseInt(m[1], 10);
      if (!imagesByPage[p]) imagesByPage[p] = [];
      imagesByPage[p].push(f);
    }
  }
} catch (e) {
  // cartella images assente o vuota, nessun problema
}

const results = [];

for (let i = 0; i < mdFiles.length; i++) {
  const md = mdFiles[i];

  const fileName = md.json.fileName || md.json.filePath || "";
  const match = fileName.match(/(?:page|pag)_?(\d+)/i);
  const pageNum = match ? parseInt(match[1], 10) : 0;

  const images = imagesByPage[pageNum] || [];
  const imageBlock = images.length > 0
    ? images.map(f => `![Immagine](./images/${f})`).join('\n\n') + '\n\n'
    : '';

  let text = "";
  try {
    const binaryBuffer = await this.helpers.getBinaryDataBuffer(i, 'data');
    text = binaryBuffer.toString('utf8');
  } catch (error) {
    text = md.json.markdown || md.json.content || md.json.text || md.json.fileContent || "";
  }

  if (text) {
    text = text.replace(/^\s*[-*+]\s*[•●▪◦⌂]\s*/gm, '- ');
    text = text.replace(/^\s*[-*+]\s+e\s+/gm, '- ');
    text = text.replace(/[ \t]+/g, ' ');
    text = text.replace(/\n{3,}/g, '\n\n');
  }

  results.push({
    json: {
      fileName,
      projectName,
      page: pageNum,
      finalContent: `# ${projectName} - Pagina ${pageNum}\n\n${imageBlock}${text.trim()}`
    }
  });
}

return results;

