const REPLACEMENTS = {
  "N©ATT": "N° ATT.",
  "EFIfi": "Elfi",
  "TS UN": "TS U",
  "erriero": "guerriero",
  "dii rosso": "di rosso",
  "@apelli": "capelli",
  "ritor- neranno": "ritorneranno",
  "oDUNGEONS": "DUNGEONS",
  "GoDRAGONS": "DRAGONS",
  "DUNGEONS GoDRAGONS": "DUNGEONS & DRAGONS",
  "DUNGEONS &DRAGONS": "DUNGEONS & DRAGONS",
  "DUNGEONS&DRAGONS": "DUNGEONS & DRAGONS",
  "registratò": "registrato",
  "registrat0": "registrato",
};

let markdown = $input.item.json.markdown;

if (markdown) {
  // 1. Unione automatica e preventiva dei trattini a fine riga
  markdown = markdown.replace(/(\w+)-\s*\n*(\w+)/g, '$1$2');

  // 2. Applicazione del dizionario dei restauri
  for (const [badText, goodText] of Object.entries(REPLACEMENTS)) {
    const safeBadText = badText.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const regex = new RegExp(safeBadText, 'g');
    markdown = markdown.replace(regex, goodText);
  }

  // 3. OCR: lettera minuscola incollata davanti a parola TUTTO-MAIUSCOLO
  markdown = markdown.replace(/(^|[\s\(,])[a-z]{1,2}([A-Z]{3,}\b)/g, '$1$2');

  // 4. Rimuovi righe con soli 1-2 caratteri non significativi
  markdown = markdown.replace(/^[ \t]*[=\|][ \t]*$/gm, '');
  markdown = markdown.replace(/^[ \t]*\.[ \t]*$/gm, '');
  markdown = markdown.replace(/^[ \t]*[a-z]{1,2}[ \t]*$/gm, '');

  // 5. Rimuovi righe OCR garbage (alta densità di caratteri speciali non markdown)
  markdown = markdown.split('\n').map(line => {
    const t = line.trim();
    if (!t || t.startsWith('#') || t.startsWith('!') || t.startsWith('[') || t.startsWith('-')) return line;
    const specials = (t.match(/[{}[\]\\\/~^`<>]/g) || []).length;
    if (specials >= 2 && specials / t.length > 0.15) return '';
    return line;
  }).join('\n');

  $input.item.json.markdown = markdown;
}

return $input.item;

