const fs = require('fs');
const items = $input.all();
const projectName = items[0]?.json?.projectName || $('Split Out').first().json.projectName;

const capitoliDir = `/shared/projects/${projectName}/capitoli`;

// Pulisci la directory prima di ogni run per evitare accumulo di vecchi file
if (fs.existsSync(capitoliDir)) {
  for (const f of fs.readdirSync(capitoliDir)) {
    fs.unlinkSync(`${capitoliDir}/${f}`);
  }
}
fs.mkdirSync(capitoliDir, { recursive: true });

// Concatena le pagine rimuovendo il wrapper "# Progetto - Pagina N"
const texts = items.map(item => {
  let content = item.json.finalContent || '';
  content = content.replace(/^# .+? - Pagina \d+\s*\n/, '');
  return content.trim();
});

let fullText = texts.join('\n\n<!-- pb -->\n\n');

// === PULIZIA GIUNZIONI DI PAGINA ===
// 1. Parola sillabata a fine pagina
fullText = fullText.replace(/(\w)-\n\n<!-- pb -->\n\n(\w)/g, '$1$2');
// 2. Frase che continua oltre il salto pagina
fullText = fullText.replace(/([^.!?:;»")\]\n])\n\n<!-- pb -->\n\n([a-zà-ü])/g, '$1 $2');
// 3. Rimuove i marcatori rimasti
fullText = fullText.replace(/\n*<!-- pb -->\n*/g, '\n\n');
// 4. Normalizza spazi
fullText = fullText.replace(/\n{3,}/g, '\n\n');

// === SPLIT PER CAPITOLI (heading ## livello 2) ===
const parts = fullText.split(/(?=^## )/m).filter(p => p.trim());

if (parts.length === 0) {
  const filename = `${capitoliDir}/01-completo.md`;
  fs.writeFileSync(filename, fullText, 'utf8');
  return [{ json: { salvati: 1, files: [filename], projectName } }];
}

const savedFiles = [];
for (let i = 0; i < parts.length; i++) {
  const content = parts[i].trim();
  const firstLine = content.split('\n')[0].trim();
  const title = firstLine.replace(/^#+\s*/, '').trim();
  const slug = title
    .toLowerCase()
    .replace(/[àáâä]/g, 'a').replace(/[èéêë]/g, 'e')
    .replace(/[ìíîï]/g, 'i').replace(/[òóôö]/g, 'o').replace(/[ùúûü]/g, 'u')
    .replace(/[^a-z0-9.]+/g, '-').replace(/^-|-$/g, '').slice(0, 60);
  const filename = `${capitoliDir}/${String(i + 1).padStart(2, '0')}-${slug}.md`;
  fs.writeFileSync(filename, content, 'utf8');
  savedFiles.push({ index: i + 1, title, filename });
}

return [{ json: { salvati: savedFiles.length, files: savedFiles, projectName } }];

const fs = require('fs');
const projectName = $input.item.json.projectName;
const errorsPath = `/shared/projects/qa/errors/${projectName}.json`;
fs.mkdirSync('/shared/projects/qa/errors', { recursive: true });
fs.writeFileSync(errorsPath, '[]', 'utf8');
return $input.item;

const fs = require('fs');
const item = $input.item;
const markdown = item.json.markdown || '';
const pageNum = $('Loop Over Items').item.json.pages?.page || 0;
const projectName = $('Loop Over Items').item.json.projectName || '';
const errorsPath = `/shared/projects/qa/errors/${projectName}.json`;
const errors = [];

// 1. Garbage nelle celle tabella HTML
const rowRegex = /<tr>([\s\S]*?)<\/tr>/gi;
let rowMatch;
while ((rowMatch = rowRegex.exec(markdown)) !== null) {
  const row = rowMatch[1];
  const cells = [];
  const cellRegex = /<td>([^<]*)<\/td>/g;
  let cm;
  while ((cm = cellRegex.exec(row)) !== null) cells.push(cm[1].trim());
  cells.forEach((cell, idx) => {
    if (!cell || cell.length < 2) return;
    const letters = (cell.match(/[a-zA-ZàèéìòùÀÈÉÌÒÙ ]/g) || []).length;
    const ratio = letters / cell.length;
    const hasSymbols = /[0-9\(\)\[\]{}\\\/~^|]/.test(cell);
    if (ratio < 0.4 && hasSymbols) {
      const context = cells.filter((c, i) => i !== idx && c).join(' | ').substring(0, 80);
      errors.push({ page: pageNum, type: 'table_garbage', context, column_index: idx, found: cell });
    }
  });
}

// 2. Lingua straniera
const ptWords = /\b(também|baixo|quartos|falar|beber|então|muito|todos)\b/i;
const esWords = /\b(también|están|tienen|pueden|este|esta|pero|todo)\b/i;
const ptMatch = markdown.match(ptWords);
const esMatch = markdown.match(esWords);
if (ptMatch || esMatch) {
  errors.push({ page: pageNum, type: 'wrong_language',
    language: ptMatch ? 'portuguese' : 'spanish', found: (ptMatch || esMatch)[0] });
}

if (errors.length > 0) {
  let existing = [];
  try { existing = JSON.parse(fs.readFileSync(errorsPath, 'utf8')); } catch (e) {}
  existing.push(...errors);
  fs.writeFileSync(errorsPath, JSON.stringify(existing, null, 2), 'utf8');
}
return item;

const fs = require('fs');
const projectName = $('Split Out').first().json.projectName;
const errorsPath = `/shared/projects/qa/errors/${projectName}.json`;
const solutionsPath = `/shared/projects/qa/solutions.json`;
const markdownDir = `/shared/projects/${projectName}/markdown`;

let errors = [];
try { errors = JSON.parse(fs.readFileSync(errorsPath, 'utf8')); } catch (e) {}
if (errors.length === 0) return $input.all();

let solutions = [];
try { solutions = JSON.parse(fs.readFileSync(solutionsPath, 'utf8')); } catch (e) {}

const hasSol = (err) => solutions.some(s => s.wrong === err.found);
const withSol    = errors.filter(hasSol);
const withoutSol = errors.filter(e => !hasSol(e));

// Applica soluzioni ai file su disco + items in memoria
if (withSol.length > 0) {
  const pages = [...new Set(withSol.map(e => e.page))];
  for (const pageNum of pages) {
    const pagePath = `${markdownDir}/page_${pageNum}.md`;
    try {
      let content = fs.readFileSync(pagePath, 'utf8');
      for (const err of withSol.filter(e => e.page === pageNum)) {
        const sol = solutions.find(s => s.wrong === err.found);
        if (sol) content = content.split(err.found).join(sol.correct);
      }
      fs.writeFileSync(pagePath, content, 'utf8');
    } catch (e) {}
  }
  for (const item of $input.all()) {
    const fn = item.json.fileName || item.json.filePath || '';
    const pm = fn.match(/page_(\d+)\.md$/);
    if (!pm) continue;
    const pageNum = parseInt(pm[1]);
    const pageErrs = withSol.filter(e => e.page === pageNum);
    if (pageErrs.length === 0) continue;
    let content = item.json.markdown || '';
    for (const err of pageErrs) {
      const sol = solutions.find(s => s.wrong === err.found);
      if (sol) content = content.split(err.found).join(sol.correct);
    }
    item.json.markdown = content;
    item.binary = {};
  }
}

if (withoutSol.length > 0) {
  const summary = withoutSol
    .map(e => `  Pag.${e.page} [${e.type}]: "${e.found}"${e.context ? ' ('+e.context+')' : ''}`)
    .join('\n');
  throw new Error(
    `Trovati ${withoutSol.length} errori senza soluzione.\nFile: ${errorsPath}\n\n${summary}\n\nAggiungi le correzioni in ${solutionsPath} e rilancia il workflow.`
  );
}
return $input.all();
